from __future__ import annotations

import base64
import io
from typing import Final

import streamlit as st
from PIL import Image
from streamlit_image_coordinates import streamlit_image_coordinates


TITLE: Final = "※本当にあった　通信障害診断シミュレーター"

# 画像はPythonファイル内へ埋め込んでいます。
# streamlit_app.py と requirements.txt の2ファイルだけで動作します。
MAP_IMAGE_B64: Final = """"""

# 画像をカラム内に入れず、ページ中央へ単独で表示します。
# 前回より横幅に余裕を持たせ、右端が見切れにくい構成です。
DISPLAY_WIDTH: Final = 950


@st.cache_resource
def load_map_image() -> Image.Image:
    raw = base64.b64decode(MAP_IMAGE_B64)
    return Image.open(io.BytesIO(raw)).convert("RGB")


MAP_IMAGE = load_map_image()
DISPLAY_HEIGHT: Final = round(DISPLAY_WIDTH * MAP_IMAGE.height / MAP_IMAGE.width)


