# =========================================================
# メイン画面
# =========================================================

def render_map() -> None:
    # 結果ポップアップを表示中は、背後の画像クリックを処理しない。
    if st.session_state.interaction_phase == "showing_result":
        st.image(MAP_IMAGE, width=DISPLAY_WIDTH)
        return

    left_space, image_col, right_space = st.columns([0.04, 0.92, 0.04])

    with image_col:
        click = streamlit_image_coordinates(
            MAP_IMAGE,
            width=DISPLAY_WIDTH,
            key=(
                f"network_map_"
                f"{st.session_state.current_step}_"
                f"{st.session_state.map_generation}"
            ),
        )

    if not click:
        return

    click_key = (
        int(click["x"]),
        int(click["y"]),
        st.session_state.current_step,
        st.session_state.map_generation,
    )

    # 同じクリックイベントを再実行時に処理し直さない。
    if click_key == st.session_state.last_processed_click:
        return

    st.session_state.last_processed_click = click_key

    target = find_target(
        int(click["x"]),
        int(click["y"]),
    )

    if target is None:
        st.session_state.selected_target = None
        st.session_state.last_wrong_target = None
        st.session_state.interaction_phase = "awaiting_selection"
        return

    st.session_state.selected_target = target
    current = STEPS[st.session_state.current_step]

    if target in current["allowed_targets"]:
        st.session_state.last_wrong_target = None
        st.session_state.interaction_phase = "ready_to_confirm"
    else:
        st.session_state.last_wrong_target = target
        st.session_state.interaction_phase = "awaiting_selection"


def render_current_investigation() -> None:
    step = STEPS[st.session_state.current_step]
    selected = st.session_state.selected_target

    st.subheader("現在の調査")

    st.progress(
        (st.session_state.current_step + 1) / len(STEPS)
    )

    st.write(
        f"調査 {step['number']} / {len(STEPS)}"
    )

    if selected is None:
        return

    st.markdown("### 選択中")
    st.write(TARGET_LABELS[selected])

    if selected in step["allowed_targets"]:
        st.button(
            step["action"],
            key=f"confirm_step_{st.session_state.current_step}",
            type="primary",
            use_container_width=True,
            on_click=complete_current_step,
        )

    else:
        st.warning(
            "この場所では現在、確認できる項目はありません。"
            "別の機器やケーブルを調べてください。"
        )


def render_eliminated() -> None:
    st.subheader("可能性が低くなった原因")

    eliminated = []
    for step in st.session_state.log:
        eliminated.extend(step["eliminates"])

    if not eliminated:
        st.caption(
            "調査を進めると、ここに切り分け結果が表示されます。"
        )
        return

    for item in dict.fromkeys(eliminated):
        st.write(f"✅ {item}")


def render_log() -> None:
    st.subheader("調査記録")

    if not st.session_state.log:
        st.caption("まだ確認は行われていません。")
        return

    for step in reversed(st.session_state.log):
        with st.expander(
            f"調査 {step['number']}：{step['action']}"
        ):
            st.markdown("**確認結果**")
            st.write(step["result"])

            st.markdown("**この結果から分かること**")
            st.info(step["meaning"])


def open_intro_dialog() -> None:
    st.session_state.show_intro = True


def render_main() -> None:
    st.title(TITLE)

    st.caption(
        "実際に起きた通信障害をもとに、"
        "原因の切り分けを体験します。"
    )

    st.button(
        "状況説明をもう一度見る",
        on_click=open_intro_dialog,
    )

    # ネットワーク構成図をページ幅いっぱいに表示
    render_map()

    st.divider()

    investigation_col, eliminated_col = st.columns(
        [1.15, 1],
        gap="large",
    )

    with investigation_col:
        render_current_investigation()

    with eliminated_col:
        render_eliminated()

    st.divider()
    render_log()

    if (
        st.session_state.show_result
        and st.session_state.interaction_phase == "showing_result"
    ):
        result_dialog()

    if st.session_state.show_finish:
        finish_dialog()


# =========================================================
# アプリ実行
# =========================================================

st.set_page_config(
    page_title=TITLE,
    page_icon="🔎",
    layout="wide",
    initial_sidebar_state="collapsed",
)

initialize_state()

if st.session_state.screen == "title":
    render_title()

else:
    if st.session_state.show_intro:
        intro_dialog()

    render_main()
